/// <summary>
/// Extension of class SalesInvoiceDPBase
/// </summary>
[ExtensionOf(classStr(SalesInvoiceDPBase))]
final class AVASalesInvoiceDPBaseCls_Extension
{
    public Notes avaCachedHeaderNotes_Top, avaCachedHeaderNotes_Bottom;

}

Method.Source:
/// <summary>
/// Extension of init method
/// </summary>
/// <param name = "_custInvoiceJour">CustInvoiceJour</param>
protected void init(CustInvoiceJour _custInvoiceJour)
{
    next init(_custInvoiceJour);

    avaCachedHeaderNotes_Bottom = this.avaGetDocumentNote(_custInvoiceJour, custFormLetterDocument, AVATCVNotePosition::Bottom);
    avaCachedHeaderNotes_Top    = this.avaGetDocumentNote(_custInvoiceJour, custFormLetterDocument, AVATCVNotePosition::Top);
}

/// <summary>
/// Gets the note that has been attached to the invoice.
/// </summary>
/// <param name="_common">
/// A <c>Common</c> record that either contains the header information or line information.
/// </param>
/// <param name="_custFormLetterDocument">
/// The <c>CustFormLetterDocument</c> record.
/// </param>
/// <param name="_avaNotePosition">
/// The <c>AVATCVNotePosition</c> enum value.
/// </param>
/// <returns>
/// The note that has been attached to the invoice.
/// </returns>
/// <exception cref="M:Exception::Error">
/// If the <c>common</c> record is not a <c>CustInvoiceJour</c> record or <c>CustInvoiceTrans</c>
/// record.
/// </exception>
public Notes avaGetDocumentNote(Common _common, CustFormLetterDocument _custFormLetterDocument, AVATCVNotePosition _avaNotePosition)
{
    Notes notes;
    var docuOnFormular = this.getDocuOnFormular(_common);

    if (_custFormLetterDocument.DocuOnInvoice == docuOnFormular ||
        _custFormLetterDocument.DocuOnInvoice == DocuOnFormular::All &&
        _avaNotePosition == AVATCVNotePosition::Top)
    {
        var docuRefSearch   = DocuRefSearch::KCS_TCVNewTypeAndRestrictAndPTypeAndPos(
                                _common,
                                _custFormLetterDocument.DocuTypeInvoice,
                                DocuRestriction::External,
                                AVATCVPaperType::Invoice,
                                AVATCVNotePosition::Top);

        notes = Docu::concatDocuRefNotes(docuRefSearch);
    }
    if (_custFormLetterDocument.DocuOnInvoice == docuOnFormular ||
        _custFormLetterDocument.DocuOnInvoice == DocuOnFormular::All &&
        _avaNotePosition == AVATCVNotePosition::Bottom)
    {
        var docuRefSearch   = DocuRefSearch::KCS_TCVNewTypeAndRestrictAndPTypeAndPos(
                                _common,
                                _custFormLetterDocument.DocuTypeInvoice,
                                DocuRestriction::External,
                                AVATCVPaperType::Invoice,
                                AVATCVNotePosition::Bottom);

        notes = Docu::concatDocuRefNotes(docuRefSearch);
    }

    return notes;
}
